```javascript
import { gsap } from 'gsap';
import { MeshStandardNodeMaterial } from 'three/webgpu';

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const { Group, Mesh, PlaneGeometry, Color } = THREE;

  const group = new Group();
  group.userData.handlers = {};
  const timelines = [];
  const materials = [];
  const geometries = [];

  // Dimensions
  const cardW = 2.4;
  const cardH = 3.2;
  const hdrH = 0.08;
  const ctaW = 1.4;
  const ctaH = 0.36;

  // Colors from spec
  const colors = {
    surface: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    ink: '#16161d'
  };

  // Card background plane
  const cardGeo = new PlaneGeometry(cardW, cardH);
  const cardMat = new MeshStandardNodeMaterial({
    color: new Color(colors.surface),
    roughness: 0.7,
    metalness: 0
  });
  materials.push(cardMat);
  geometries.push(cardGeo);

  const cardMesh = new Mesh(cardGeo, cardMat);
  group.add(cardMesh);

  // Header strip: machined metal effect
  const hdrGeo = new PlaneGeometry(cardW, hdrH);
  const hdrMat = new MeshStandardNodeMaterial({
    color: new Color(colors.surface),
    roughness: 0.55,
    metalness: 0.5,
    clearcoat: 0.2
  });
  materials.push(hdrMat);
  geometries.push(hdrGeo);

  const hdrMesh = new Mesh(hdrGeo, hdrMat);
  hdrMesh.position.y = cardH / 2 - hdrH / 2;
  hdrMesh.position.z = 0.001;
  group.add(hdrMesh);

  // Layout: top-down positioning
  let y = 1.3;

  // Tier name: ATELIER RESERVE
  const tierText = ctx.fontAtlas.createText('ATELIER RESERVE', {
    fontSize: 20,
    color: colors.paper,
    align: 'center',
    letterSpacingPx: 1.6
  });
  tierText.position.set(0, y, 0.01);
  group.add(tierText);
  y -= 0.5;

  // Price: $480
  const priceText = ctx.fontAtlas.createText('$480', {
    fontSize: 62,
    color: colors.paper,
    align: 'center'
  });
  priceText.position.set(0, y, 0.01);
  group.add(priceText);
  y -= 0.7;

  // Caption: PER MONTH, BILLED ANNUALLY
  const captionText = ctx.fontAtlas.createText('PER MONTH, BILLED ANNUALLY', {
    fontSize: 9,
    color: colors.paper,
    align: 'center',
    letterSpacingPx: 1.08
  });
  captionText.position.set(0, y, 0.01);
  group.add(captionText);
  y -= 0.5;

  // Features: four rows with fade-up animation
  const features = [
    'Quarterly movement service',
    'Priority commission slots',
    'Private fitting lounge access',
    'Lifetime case refinishing'
  ];

  const featureMeshes = [];
  const featureTargetY = [];

  for (const feat of features) {
    const targetY = y;
    featureTargetY.push(targetY);

    const fMesh = ctx.fontAtlas.createText(feat, {
      fontSize: 13,
      color: colors.paper,
      align: 'left'
    });
    // Position offset upward for fade-up animation entrance
    fMesh.position.set(-0.8, targetY + 0.2, 0.01);
    group.add(fMesh);
    featureMeshes.push(fMesh);
    y -= 0.4;
  }

  // CTA button: gradient accent row
  y -= 0.15;

  const ctaGeo = new PlaneGeometry(ctaW, ctaH);
  const ctaMat = new MeshStandardNodeMaterial({
    color: new Color(colors.accent),
    emissive: new Color(colors.accent),
    emissiveIntensity: 1.5,
    roughness: 0.6,
    metalness: 0.3
  });
  materials.push(ctaMat);
  geometries.push(ctaGeo);

  const ctaMesh = new Mesh(ctaGeo, ctaMat);
  ctaMesh.position.set(0, y, 0.01);
  group.add(ctaMesh);

  // CTA label: JOIN THE RESERVE
  const ctaLabel = ctx.fontAtlas.createText('JOIN THE RESERVE', {
    fontSize: 13,
    color: colors.ink,
    align: 'center',
    letterSpacingPx: 1.04
  });
  ctaLabel.position.set(0, y, 0.02);
  group.add(ctaLabel);

  // ===== ANIMATIONS =====

  // Weighted settle: scale 1.04 → 1.0 over 900ms
  group.scale.set(1.04, 1.04, 1.04);
  const settleTL = gsap.to(group.scale, {
    x: 1,
    y: 1,
    z: 1,
    duration: 0.9,
    ease: 'cubic-bezier(0.165, 0.84, 0.44, 1)'
  });
  timelines.push(settleTL);

  // Feature fade-up entrance: opacity 0→1, y +0.2→0, 80ms stagger
  gsap.set(featureMeshes, { opacity: 0 });
  const fadeupTL = gsap.to(featureMeshes, {
    opacity: 1,
    y: (i) => featureTargetY[i],
    duration: 0.5,
    ease: 'cubic-bezier(0.25, 0.46, 0.45, 0.94)',
    stagger: 0.08
  });
  timelines.push(fadeupTL);

  // CTA press interaction
  group.userData.handlers.ctaClick = () => {
    const pressTL = gsap.timeline();
    pressTL.to(ctaMesh.scale, {
      x: 0.97,
      y: 0.97,
      z: 1,
      duration: 0.12,
      ease: 'cubic-bezier(0.175, 0.885, 0.32, 1.275)'
    });
    pressTL.to(ctaMesh.scale, {
      x: 1,
      y: 1,
      z: 1,
      duration: 0.2,
      ease: 'power2.out'
    });
    timelines.push(pressTL);
  };

  // Cleanup and resource disposal
  group.userData.cleanup = () => {
    timelines.forEach(tl => tl.kill());
    materials.forEach(mat => mat.dispose());
    geometries.forEach(geo => geo.dispose());
  };

  return group;
}
